local manager
local language

Lang = {}

if isLocalWin then
    ShellInterface.getLanguageDetail = function(_, code)
        if code == nil or code == "" then
            return "zh"
        else
            return code
        end
    end
end

function Lang:init()
    manager = LanguageManager.Instance()
    manager:loadCustomLang(FileUtil:getSettingPath())
    language = manager:getCurrentLanguage()
end

---@return string
function Lang:getString(key)
    if not manager or not key then
        return (key or "nil")
    end
    return manager:getString(key)
end

---@return string
function Lang:getItemName(itemId, meta)
    if not manager then
        return ""
    end
    return manager:getItemName(itemId, meta or 0)
end

---@return string
function Lang:format(key, ...)
    return string.format(Lang:getString(key), ...)
end

function Lang:getTipString(tip, text)
    text = text or ""
    return MultiLanTipSetting.getMessageToLua(language, tip, text)
end

function Lang:getLang()
    return language
end

return Lang